package main

import (
	"bytes"
	"flag"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"github.com/taybart/go-erde/luagen"
	"github.com/taybart/go-erde/parse"
)

// compiledFooter marks Lua files generated by `erde compile`. Same as the
// reference compiler, so either CLI recognizes the other's output.
const compiledFooter = "-- __ERDE_COMPILED__"

const compileUsage = `Usage: erde compile [options] [paths]
Compiles Erde files (or all *.erde files under directories) into Lua, writing
foo.erde to foo.lua. Paths default to the current directory.
Available options are:
  -o dir   output directory for compiled files
  -f       overwrite existing Lua files (by default only files generated by
           'erde compile' are overwritten)
  -p       print compiled code instead of writing files
  -X list  enable experimental erde extensions (comma separated: ` + "%s" + `)`

// compileCommand implements `erde compile`, mirroring the reference compiler's
// CLI (https://erde-lang.github.io/docs/cli).
func compileCommand(args []string) int {
	var opt_o, opt_x string
	var opt_f, opt_p bool
	flags := flag.NewFlagSet("compile", flag.ContinueOnError)
	flags.StringVar(&opt_o, "o", "", "")
	flags.StringVar(&opt_x, "X", "", "")
	flags.BoolVar(&opt_f, "f", false, "")
	flags.BoolVar(&opt_p, "p", false, "")
	flags.SetOutput(io.Discard)
	flags.Usage = func() {}

	paths, err := parseInterspersed(flags, args)
	if err == flag.ErrHelp {
		fmt.Printf(compileUsage+"\n", strings.Join(parse.ErdeExperiments, ", "))
		return 0
	} else if err != nil {
		fmt.Println(err.Error())
		return 1
	}

	var erdeOpts parse.ErdeOptions
	if err := erdeOpts.Enable(opt_x); err != nil {
		fmt.Println(err.Error())
		return 1
	}

	if len(paths) == 0 {
		paths = []string{"."}
	}

	for _, root := range paths {
		info, err := os.Stat(root)
		if err != nil {
			fmt.Println(err.Error())
			return 1
		}

		// Explicitly named files are compiled whatever their extension.
		if !info.IsDir() {
			if !compileFile(root, opt_o, opt_f, opt_p, erdeOpts) {
				return 1
			}
			continue
		}

		err = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if !d.IsDir() && strings.HasSuffix(path, ".erde") {
				if !compileFile(path, opt_o, opt_f, opt_p, erdeOpts) {
					return errCompileFailed
				}
			}
			return nil
		})
		if err == errCompileFailed {
			return 1
		} else if err != nil {
			fmt.Println(err.Error())
			return 1
		}
	}

	return 0
}

var errCompileFailed = fmt.Errorf("compile failed")

const cleanUsage = `Usage: erde clean [paths]
Removes Lua files generated by 'erde compile' (files ending w/ the '` + compiledFooter + `'
footer), or all such files under directories. Paths default to the current
directory. Other Lua files are never removed.`

// cleanCommand implements `erde clean`, mirroring the reference compiler's CLI.
func cleanCommand(args []string) int {
	flags := flag.NewFlagSet("clean", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	flags.Usage = func() {}

	paths, err := parseInterspersed(flags, args)
	if err == flag.ErrHelp {
		fmt.Println(cleanUsage)
		return 0
	} else if err != nil {
		fmt.Println(err.Error())
		return 1
	}

	if len(paths) == 0 {
		paths = []string{"."}
	}

	status := 0
	for _, root := range paths {
		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() || !strings.HasSuffix(path, ".lua") || !isCompiledFile(path) {
				return nil
			}
			if err := os.Remove(path); err != nil {
				fmt.Printf("%s => ERROR\n%s\n", path, err)
				status = 1
				return nil
			}
			fmt.Printf("%s => DELETED\n", path)
			return nil
		})
		if err != nil {
			fmt.Println(err.Error())
			status = 1
		}
	}

	return status
}

func compileFile(path, outdir string, force, print bool, erdeOpts parse.ErdeOptions) bool {
	compilePath := strings.TrimSuffix(path, ".erde") + ".lua"
	if outdir != "" {
		compilePath = filepath.Join(outdir, compilePath)
	}

	if !print && !force && fileExists(compilePath) && !isCompiledFile(compilePath) {
		fmt.Printf("%s => ERROR\n", path)
		fmt.Printf("Cannot write to %s: file already exists (use -f to overwrite)\n", compilePath)
		return false
	}

	source, err := os.ReadFile(path)
	if err != nil {
		fmt.Printf("%s => ERROR\n%s\n", path, err)
		return false
	}

	chunk, err := parse.ParseErdeWithOptions(bytes.NewReader(source), path, erdeOpts)
	if err != nil {
		fmt.Printf("%s => ERROR\n%s\n", path, err)
		return false
	}

	compiled := luagen.Generate(chunk)
	if !strings.HasSuffix(compiled, "\n") {
		compiled += "\n"
	}
	compiled += compiledFooter

	if print {
		fmt.Println(path)
		fmt.Println(strings.Repeat("-", len(path)))
		fmt.Println(compiled)
		return true
	}

	if err := os.MkdirAll(filepath.Dir(compilePath), 0o755); err != nil {
		fmt.Printf("%s => ERROR\n%s\n", path, err)
		return false
	}
	if err := os.WriteFile(compilePath, []byte(compiled), 0o644); err != nil {
		fmt.Printf("%s => ERROR\n%s\n", path, err)
		return false
	}

	fmt.Printf("%s => %s\n", path, compilePath)
	return true
}

func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// isCompiledFile checks whether a Lua file was generated by `erde compile`
// (ends w/ compiledFooter, allowing for a trailing newline added by editors).
func isCompiledFile(path string) bool {
	source, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	return strings.HasSuffix(strings.TrimRight(string(source), "\r\n"), compiledFooter)
}

// parseInterspersed parses flags that may come after positional args (ex.
// `erde compile src -o dest`), which the flag package doesn't support.
func parseInterspersed(flags *flag.FlagSet, args []string) ([]string, error) {
	var positional []string
	for {
		if err := flags.Parse(args); err != nil {
			return nil, err
		}
		args = flags.Args()
		if len(args) == 0 {
			return positional, nil
		}
		positional = append(positional, args[0])
		args = args[1:]
	}
}
